package main

import (
	"fmt"
	"sort"
)

func main() {
	var n, l, d, p, nl, nd, np int
	fmt.Scan(&n)
	fmt.Scan(&l)
	l *= l // Wait, Java: l = s.nextInt() * s.nextInt()
	// Let's re-read Java carefully.
	// int n = s.nextInt(), l = s.nextInt() * s.nextInt(), d = s.nextInt() * s.nextInt(), p = s.nextInt(), 
	// nl = n * s.nextInt(), nd = n, np = n * s.nextInt();

	// So input order: n, k, l, c, d, p, nl, np? No.
	// s.nextInt() calls sequence:
	// 1. n
	// 2. l_part1
	// 3. l_part2 -> l = l_part1 * l_part2
	// 4. d_part1
	// 5. d_part2 -> d = d_part1 * d_part2
	// 6. p
	// 7. nl_part -> nl = n * nl_part
	// 8. np_part -> np = n * np_part
	// nd = n

	var tmp int
	fmt.Scan(&n)
	fmt.Scan(&tmp)
	l = tmp
	fmt.Scan(&tmp)
	l *= tmp
	fmt.Scan(&tmp)
	d = tmp
	fmt.Scan(&tmp)
	d *= tmp
	fmt.Scan(&p)
	fmt.Scan(&tmp)
	nl = n * tmp
	nd = n
	fmt.Scan(&tmp)
	np = n * tmp

	c := make([]int, 3)
	c[0] = l / nl
	c[1] = d / nd
	c[2] = p / np
	sort.Ints(c)
	fmt.Println(c[0])
}

